mapper.select:
SELECT R.CHATTING_ROOM_NO,
/* 상대방 번호: 내가 OPEN_MEMBER면 PARTICIPANT, 아니면 OPEN_MEMBER */ CASE WHEN R.OPEN_MEMBER = #{memberNo} THEN R.PARTICIPANT ELSE R.OPEN_MEMBER END AS TARGET_NO,
/* 상대방 닉네임 */ CASE WHEN R.OPEN_MEMBER = #{memberNo} THEN M2.NICKNAME ELSE M1.NICKNAME END AS TARGET_NICKNAME,
/* 상대방 프로필 이미지 */ CASE WHEN R.OPEN_MEMBER = #{memberNo} THEN M2.PROFILE_IMAGE ELSE M1.PROFILE_IMAGE END AS TARGET_PROFILE,
/* 마지막 메시지 */ (SELECT MESSAGE_CONTENT FROM MESSAGE WHERE CHATTING_ROOM_NO = R.CHATTING_ROOM_NO ORDER BY MESSAGE_NO DESC FETCH FIRST 1 ROWS ONLY ) AS LAST_MESSAGE,
/* 마지막 메시지 시간 */ (SELECT TO_CHAR(SEND_TIME, 'YYYY-MM-DD HH24:MI') FROM MESSAGE WHERE CHATTING_ROOM_NO = R.CHATTING_ROOM_NO ORDER BY MESSAGE_NO DESC FETCH FIRST 1 ROWS ONLY ) AS SEND_TIME,
/* 읽지 않은 메시지 수 */ (SELECT COUNT(*) FROM MESSAGE WHERE CHATTING_ROOM_NO = R.CHATTING_ROOM_NO AND SENDER_NO != #{memberNo} AND READ_FL = 'N' ) AS NOT_READ_COUNT
FROM CHATTING_ROOM R JOIN MEMBER M1 ON R.OPEN_MEMBER = M1.MEMBER_NO JOIN MEMBER M2 ON R.PARTICIPANT = M2.MEMBER_NO
WHERE (R.OPEN_MEMBER = #{memberNo} OR R.PARTICIPANT = #{memberNo})
ORDER BY (SELECT SEND_TIME FROM MESSAGE WHERE CHATTING_ROOM_NO = R.CHATTING_ROOM_NO ORDER BY MESSAGE_NO DESC FETCH FIRST 1 ROWS ONLY ) DESC NULLS LAST

mapper.update:
UPDATE MESSAGE
SET READ_FL = 'Y'
WHERE CHATTING_ROOM_NO = #{chattingRoomNo}
  AND SENDER_NO != #{memberNo}
  AND READ_FL = 'N'
